const lockInstanceHealth = `-- name: LockInstanceHealth :one
SELECT domain, state, since, failure_days, last_failure_day FROM instance_health WHERE domain = $1
FOR UPDATE
`

// LockInstanceHealth reads the health of a server in the transaction that updates it and locks
// the row, so that concurrent deliveries to one server do not lose an update.
func (q *Queries) LockInstanceHealth(ctx context.Context, domain string) (InstanceHealth, error) {
	row := q.db.QueryRow(ctx, lockInstanceHealth, domain)
	var i InstanceHealth
	err := row.Scan(
		&i.Domain,
		&i.State,
		&i.Since,
		&i.FailureDays,
		&i.LastFailureDay,
	)
	return i, err
}

const upsertInstanceHealth = `-- name: UpsertInstanceHealth :exec
INSERT INTO instance_health (domain, state, since, failure_days, last_failure_day)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (domain) DO UPDATE SET
  state = excluded.state,
  since = excluded.since,
  failure_days = excluded.failure_days,
  last_failure_day = excluded.last_failure_day
`

type UpsertInstanceHealthParams struct {
	Domain         string
	State          string
	Since          time.Time
	FailureDays    int32
	LastFailureDay string
}

func (q *Queries) UpsertInstanceHealth(ctx context.Context, arg UpsertInstanceHealthParams) error {
	_, err := q.db.Exec(ctx, upsertInstanceHealth,
		arg.Domain,
		arg.State,
		arg.Since,
		arg.FailureDays,
		arg.LastFailureDay,
	)
	return err
}
